python3 -c "
import json
with open('/app/resources/treasury_bulletin_1970_08.json', 'r') as f:
    data = json.load(f)

# Search for table containing savings bonds data
def find_tables(element):
    results = []
    if isinstance(element, dict):
        if element.get('type') == 'table':
            results.append(element)
        for v in element.values():
            results.extend(find_tables(v))
    elif isinstance(element, list):
        for item in element:
            results.extend(find_tables(item))
    return results

tables = find_tables(data)
print(f'Found {len(tables)} tables')
if tables:
    # Print first table's structure
    t = tables[0]
    print('Table keys:', t.keys() if isinstance(t, dict) else 'not dict')
"
